#include <bits/stdc++.h>
using namespace std;

vector<int> prefix_function(const string& pattern) {
    int n = static_cast<int>(pattern.size());
    vector<int> border(n);
    for (int i = 1; i < n; ++i) {
        int length = border[i - 1];
        while (length > 0 && pattern[i] != pattern[length]) {
            length = border[length - 1];
        }
        if (pattern[i] == pattern[length]) {
            ++length;
        }
        border[i] = length;
    }
    return border;
}

vector<int> find_occurrences(const string& text, const string& pattern) {
    vector<int> border = prefix_function(pattern), positions;
    int matched = 0;
    for (int i = 0; i < static_cast<int>(text.size()); ++i) {
        while (matched > 0 && text[i] != pattern[matched]) {
            matched = border[matched - 1];
        }
        if (text[i] == pattern[matched]) {
            ++matched;
        }
        if (matched == static_cast<int>(pattern.size())) {
            positions.push_back(i - matched + 2);
            matched = border[matched - 1];
        }
    }

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string pattern, text;
    cin >> text >> pattern;
    vector<int> positions = find_occurrences(text, pattern);
    cout << positions.size() << '\n';
    for (int i = 0; i < static_cast<int>(positions.size()); ++i) {
        cout << positions[i] << (i + 1 == static_cast<int>(positions.size()) ? '\n' : ' ');
    }
    if (positions.empty()) {
        cout << '\n';
    }
}

